    private String name;

    Student(int id, String name) {
        if (id <= 0) throw new IllegalArgumentException("id");
        this.id = id;
        rename(name);
    }

    void rename(String name) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("name");
        this.name = name;
    }

    String name() { return name; }
}

